const KEY='tacticalQaStateV2';
const defaults=()=>({date:'2026-10-12',capacity:5,used:4,tickets:0,claimedDate:null,version:'buggy',message:'补给已就绪'});
let remote=false,current=defaults();
const load=()=>{try{return {...defaults(),...JSON.parse(localStorage.getItem(KEY)||'{}')}}catch{return defaults()}};
const save=s=>{current=s;localStorage.setItem(KEY,JSON.stringify(s));renderState(s)};
async function api(path,method='GET',data){let r=await fetch('/api'+path,{method,headers:{'content-type':'application/json'},body:data?JSON.stringify(data):undefined});if(!r.ok)throw new Error(await r.text());return r.json()}
function localClaim(){let s=load();if(s.claimedDate===s.date){s.message='今日已领取：不可重复发奖';save(s);return s}if(s.version==='buggy')s.claimedDate=s.date;if(s.used>=s.capacity){s.message='背包已满：补给发放失败';save(s);return s}s.used++;s.tickets++;s.claimedDate=s.date;s.message='领取成功：训练券 × 1';save(s);return s}
function renderState(s){current=s;document.querySelector('#bagText').textContent=`${s.used} / ${s.capacity}`;document.querySelector('#bagNavCount').textContent=`${s.used}/${s.capacity}`;document.querySelector('#dateText').textContent=s.date.replaceAll('-','.');document.querySelector('#slots').innerHTML=Array.from({length:s.capacity},(_,i)=>`<i class="slot ${i<s.used?'used':''} ${i>=s.used-s.tickets&&i<s.used?'ticket-used':''}"></i>`).join('');let f=document.querySelector('#feedback');f.textContent=s.message||s.lastMessage;f.className='feedback '+((s.message||'').includes('成功')?'ok':(s.message||'').includes('失败')||(s.message||'').includes('已领取')?'bad':'');document.querySelector('#bagDetail').textContent=`已用 ${s.used}/${s.capacity}，训练券 ${s.tickets} 张`;document.querySelector('#bagItems').innerHTML=Array.from({length:s.used},(_,i)=>`<div class="bag-item">${i>=s.used-s.tickets?'训练券 · 不可叠加':'训练道具 '+(i+1)}</div>`).join('')||'<p>背包为空</p>'}
async function refresh(){if(remote)renderState(await api('/test/state'));else renderState(load())}
document.querySelector('#claimButton').onclick=async()=>{if(remote){let r=await api('/test/claim','POST',{});renderState(r.state)}else localClaim()};
document.querySelector('#viewBag').onclick=document.querySelector('#bagNav').onclick=()=>document.querySelector('#bagDrawer').classList.add('open');document.querySelector('#closeBag').onclick=()=>document.querySelector('#bagDrawer').classList.remove('open');
window.QA_GAME={reset(o={}){let s={...defaults(),version:o.version||load().version};save(s);return s},fill(){let s=load();s.used=s.capacity;s.message='测试准备：背包已填满';save(s);return s},clear(){let s=load();s.used=0;s.tickets=0;s.message='测试准备：背包已清空';save(s);return s},advance(){let s=load(),d=new Date(s.date+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+1);s.date=d.toISOString().slice(0,10);save(s);return s},state(){return remote?current:load()}};
(async()=>{try{let h=await fetch('/api/health');remote=h.ok}catch{}await refresh()})();
